81	func resolveSelectionEmbeddingProvider(cfg *config.RouterConfig) (embedding.Provider, error) {
82		backend := embedding.BackendOverrideFromEnv()
83		if backend == "" {
84			backend = cfg.EmbeddingModels.EmbeddingBackend()
85		}
86		if backend == config.EmbeddingBackendOpenAICompatible {
87			return embedding.NewProvider(cfg.EmbeddingModels, embedding.ProviderOptions{})
88		}
89	
90		modelType := selectionEmbeddingModelType(cfg, backend)
91		switch backend {
92		case config.EmbeddingBackendOpenVINO:
93			openvinoEmbed := openvinoEmbeddingFunc(modelType)
94			return embedding.NewFuncProvider(backend, 0, func(_ context.Context, text string) ([]float32, error) {
95				return openvinoEmbed(text)
96			})
97		default:
98			return embedding.NewFuncProvider(config.EmbeddingBackendCandle, selectionEmbeddingDimension(cfg, modelType), func(_ context.Context, text string) ([]float32, error) {
99				if modelType == config.EmbeddingModelTypeQwen3 {
100					output, err := candle_binding.GetEmbeddingBatched(text, modelType, selectionEmbeddingDimension(cfg, modelType))
101					if err != nil {
102						return nil, err
103					}
104					return output.Embedding, nil
105				}
106				output, err := candle_binding.GetEmbeddingWithModelType(text, modelType, 0)
107				if err != nil {
108					return nil, err
109				}
110				return output.Embedding, nil
111			})
112		}
113	}
114	
115	func selectionEmbeddingModelType(cfg *config.RouterConfig, backend string) string {
116		modelType := cfg.EmbeddingConfig.ModelType
117		if modelType != "" {
118			return modelType
119		}
120		if backend == config.EmbeddingBackendOpenAICompatible {
121			return config.EmbeddingModelTypeRemote
122		}
123		return config.EmbeddingModelTypeQwen3
124	}
125	
126	func selectionEmbeddingDimension(cfg *config.RouterConfig, modelType string) int {
127		if cfg.EmbeddingConfig.TargetDimension > 0 {
